@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});

getCategory = () =>{
			fl_url =  "https://m.lrts.me/ajax/getCategory";
return  JSON.parse(java.ajax(fl_url)).data.bookTypeList; 
		}

	 getCategory().map($=>{	   	     	    
					 push($.name, null, 1, 1);
						list = $.subList;
		list.map(($,index)=>{	   	     	    
 	    title = $.name;	
      url = `@js:
      if(page == 1){
      url = "/ajax/getResourceList?dsize=20&entityId=${$.id}&entityType=1&pageNum=1&showFilters=1";
 }
	  else{
	  bookIds = String(source.get('bookIds')).split(",");
	  //bookIds = String(cache.getFile('bookIds')).split(",");
    maxPage = Math.floor(bookIds.length / 20);
    maxPage = bookIds.length % 20 > 0 ? maxPage + 1 : maxPage;
    if(page > maxPage) {
    url = null;
    }
    else{
    selectIndex = (page - 1) * 20;
    res = bookIds.slice(selectIndex, selectIndex + 20);
    url = "/ajax/getResourceList?dsize=20&entityId=0&entityType=0&pageNum=0&showFilters=0&bookIds="+JSON.stringify(res);
    }
}`;

			if(index+1 <= list.length - list.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);}
        });   
   });   

JSON.stringify(sort);

